#!/usr/bin/env python3
"""Verify the self-signed TLS certificate at /app/ssl/server.crt."""
import sys
from datetime import datetime, timezone

CERT_PATH = "/app/ssl/server.crt"


def load_cert():
    try:
        from cryptography import x509
        with open(CERT_PATH, "rb") as fh:
            return ("crypto", x509.load_pem_x509_certificate(fh.read()))
    except ImportError:
        import subprocess
        subprocess.run(
            ["openssl", "x509", "-in", CERT_PATH, "-noout"],
            check=True,
        )
        return ("openssl", None)


def get_common_name(backend, cert):
    if backend == "crypto":
        from cryptography.x509.oid import NameOID
        attrs = cert.subject.get_attributes_for_oid(NameOID.COMMON_NAME)
        return attrs[0].value if attrs else None
    import subprocess
    out = subprocess.check_output(
        ["openssl", "x509", "-in", CERT_PATH, "-noout", "-subject"],
        text=True,
    )
    for part in out.replace("subject=", "").replace("/", ",").split(","):
        part = part.strip()
        if part.upper().startswith("CN"):
            return part.split("=", 1)[1].strip()
    return None


def get_expiration(backend, cert):
    if backend == "crypto":
        try:
            exp = cert.not_valid_after_utc
        except AttributeError:
            exp = cert.not_valid_after.replace(tzinfo=timezone.utc)
        return exp
    import subprocess
    out = subprocess.check_output(
        ["openssl", "x509", "-in", CERT_PATH, "-noout", "-enddate"],
        text=True,
    ).replace("notAfter=", "").strip()
    return datetime.strptime(out, "%b %d %H:%M:%S %Y %Z").replace(
        tzinfo=timezone.utc
    )


def main():
    import os
    if not os.path.exists(CERT_PATH):
        print(f"ERROR: certificate not found at {CERT_PATH}")
        sys.exit(1)

    try:
        backend, cert = load_cert()
    except Exception as exc:  # noqa: BLE001
        print(f"ERROR: could not load certificate: {exc}")
        sys.exit(1)

    cn = get_common_name(backend, cert)
    exp = get_expiration(backend, cert)

    print(f"Certificate loaded from: {CERT_PATH}")
    print(f"Common Name: {cn}")
    print(f"Expiration Date: {exp.strftime('%Y-%m-%d')}")
    print("Certificate verification successful")


if __name__ == "__main__":
    main()

